const inputData = $input.all()[0];
if (!inputData) throw new Error("Nenhum dado de entrada encontrado.");
const dados = Array.isArray(inputData.json) ? inputData.json[0] : inputData.json;

// 2. Acessa a string de texto contendo o JSON traduzido pela IA
const textoBruto = dados?.candidates?.[0]?.content?.parts?.[0]?.text;
if (!textoBruto) throw new Error("Estrutura da resposta da IA inválida.");

// 3. Remove blocos de markdown caso a IA retorne encapsulada (ex: ```json ... ```)
let jsonLimpo = textoBruto.trim();
if (jsonLimpo.startsWith("```json")) {
    jsonLimpo = jsonLimpo.replace(/^```json/, "").replace(/```$/, "").trim();
} else if (jsonLimpo.startsWith("```")) {
    jsonLimpo = jsonLimpo.replace(/^```/, "").replace(/```$/, "").trim();
}

// 4. Converte a string JSON traduzida para um objeto JavaScript real
let objetoParseado;
try {
    objetoParseado = JSON.parse(jsonLimpo);
} catch (e) {
    throw new Error("A IA não retornou um JSON válido. Erro no Parse: " + e.message);
}

// 5. Substitui a chave "pt" por "en" de forma flexível (com ou sem a camada 'output' principal)
const targetBase = objetoParseado?.output?.payload_para_api?.output || 
                   objetoParseado?.payload_para_api?.output ||
                   objetoParseado?.output || 
                   objetoParseado;

if (targetBase && targetBase.pt) {
    // Cria a nova chave "en" recebendo os exatos mesmos dados de "pt"
    targetBase.en = targetBase.pt;

    // Deleta a chave "pt" antiga para manter o payload limpo
    delete targetBase.pt;
}

// 6. Retorna os dados limpos estruturados para o n8n
return [{
    json: objetoParseado
}];

