// 1. Faz uma cópia profunda do primeiro item como base
let mergedJson = JSON.parse(JSON.stringify(items[0].json));

// 2. Tenta pegar o total de blocos da base (Acessando o índice [0] do array 'output')
let blockOffset = 
  parseInt(mergedJson?.output?.[0]?.dados_de_auditoria?.total_de_blocos_gerados) || 
  parseInt(mergedJson?.dados_de_auditoria?.total_de_blocos_gerados) || 
  0;

