const items = $input.all();

// Se não houver itens, não faz nada
if (items.length === 0) {
  return [];
}

// 1. Faz uma cópia profunda do primeiro item como base
let mergedJson = JSON.parse(JSON.stringify(items[0].json));

// 2. Tenta pegar o total de blocos da base (Acessando o índice [0] do array 'output')
let blockOffset = 
  parseInt(mergedJson?.output?.[0]?.dados_de_auditoria?.total_de_blocos_gerados) || 
  parseInt(mergedJson?.dados_de_auditoria?.total_de_blocos_gerados) || 
  0;

// 3. Itera a partir do segundo item (índice 1) para juntar os dados
for (let i = 1; i < items.length; i++) {
  const currentJson = items[i].json;

  // Acha os blocos do PT no item atual (protegido contra mudanças e acessando [0])
  const currentPt = currentJson?.output?.[0]?.payload_para_api?.output?.pt || 
                    currentJson?.payload_para_api?.output?.pt;

  if (!currentPt) {
      continue;
  }

  // Acha a referência no JSON base onde os blocos serão injetados
  const targetPt = mergedJson?.output?.[0]?.payload_para_api?.output?.pt || 
                   mergedJson?.payload_para_api?.output?.pt;

  // 4. Procura por chaves de imagens e blocos no item atual
  for (const key of Object.keys(currentPt)) {
    if (key.startsWith('block-') || key.startsWith('img-')) {
      const num = parseInt(key.split('-')[1]);
      const prefix = key.split('-')[0]; 
      const newKey = `${prefix}-${blockOffset + num}`;

      // Injeta na base (ex: block-6, img-6)
      targetPt[newKey] = currentPt[key];
    }
  }

  // 5. Soma a quantidade de blocos do item atual para a próxima iteração
  const blocosAtuais = 
    parseInt(currentJson?.output?.[0]?.dados_de_auditoria?.total_de_blocos_gerados) || 
    parseInt(currentJson?.dados_de_auditoria?.total_de_blocos_gerados) || 
    0;

  blockOffset += blocosAtuais;
}

// 6. Atualiza o total de blocos gerados no JSON final
if (mergedJson?.output?.[0]?.dados_de_auditoria) {
    mergedJson.output[0].dados_de_auditoria.total_de_blocos_gerados = blockOffset;
} else if (mergedJson?.dados_de_auditoria) {
    mergedJson.dados_de_auditoria.total_de_blocos_gerados = blockOffset;
}

return [{ json: mergedJson }];
